/**
 * shim ของ SheetJS (XLSX) เท่าที่ frontend-admin/pricelist-parser.js ใช้จริง — ไม่ใช่ SheetJS ตัวเต็ม
 *
 * ★ ทำไมต้องมีไฟล์นี้: เครื่องมือนี้ควรจะเป็น SheetJS ตัวจริง (`npm install xlsx` แล้วก็อปมาวาง) แต่ `npm`
 * ใช้ไม่ได้ในสภาพแวดล้อมนี้ (ดู CLAUDE.md หัวข้อ "Environment gotchas" — EPERM lstat ของโปรไฟล์ผู้ใช้เก่า
 * ที่เครื่องนี้ไม่มีแล้ว) เลยพึ่ง Python (openpyxl มีอยู่แล้วในเครื่องนี้) เป็นตัวอ่านไฟล์ .xlsx จริงแทน
 * แล้วประกอบผลลัพธ์ให้หน้าตาเหมือนที่ `XLSX.read()` ของจริงจะคืนมา (`{SheetNames, Sheets, Workbook}`)
 *
 * รองรับเฉพาะพาธที่ pricelist-parser.js เรียกจริง: `XLSX.read(data, {type:'buffer'|'array'})` +
 * `XLSX.utils.decode_range/encode_cell` — ถ้าจะเอาไปใช้ฟีเจอร์อื่นของ SheetJS (เขียนไฟล์, สไตล์, สูตร ฯลฯ)
 * ต้องหา xlsx จริงมาแทนที่ไฟล์นี้ (เครื่องที่ npm ใช้งานได้ปกติ: `npm install xlsx` แล้วคัดลอก
 * `node_modules/xlsx/dist/xlsx.full.min.js` มาทับ)
 *
 * ต้องมี python ใน PATH (หรือกำหนด `XLSX_SHIM_PYTHON=<พาธ python>`) พร้อมแพ็กเกจ openpyxl
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

function decode_cell(addr) {
  const m = addr.match(/^([A-Z]+)(\d+)$/);
  let col = 0;
  for (let i = 0; i < m[1].length; i++) col = col * 26 + (m[1].charCodeAt(i) - 64);
  return { r: Number(m[2]) - 1, c: col - 1 };
}
function decode_range(ref) {
  const [a, b] = ref.split(':');
  return { s: decode_cell(a), e: decode_cell(b) };
}
function encode_cell(o) {
  let c = o.c, s = '';
  c++;
  while (c > 0) { const mod = (c - 1) % 26; s = String.fromCharCode(65 + mod) + s; c = Math.floor((c - 1) / 26); }
  return s + (o.r + 1);
}

function read(data, opts) {
  opts = opts || {};
  const tag = 'xlsx-shim-' + process.pid + '-' + Date.now() + '-' + Math.floor(Math.random() * 1e6);
  const tmpXlsx = path.join(os.tmpdir(), tag + '.xlsx');
  const tmpJson = path.join(os.tmpdir(), tag + '.json');
  try {
    var buf;
    if (Buffer.isBuffer(data)) buf = data;
    else if (data instanceof Uint8Array || Array.isArray(data)) buf = Buffer.from(data);
    else throw new Error('xlsx.full.min.js (shim): รองรับเฉพาะ Buffer/Uint8Array — ใช้ type:"buffer" ตอนอ่านไฟล์');
    fs.writeFileSync(tmpXlsx, buf);
    const py = process.env.XLSX_SHIM_PYTHON || 'python';
    execFileSync(py, [path.join(__dirname, 'xlsx_shim_dump.py'), tmpXlsx, tmpJson], { stdio: ['ignore', 'pipe', 'pipe'] });
    const wbJson = JSON.parse(fs.readFileSync(tmpJson, 'utf8'));
    const Sheets = {};
    Object.keys(wbJson.Sheets).forEach(function (name) {
      const raw = wbJson.Sheets[name];
      const rowsHidden = raw['!rows_hidden'] || [], colsHidden = raw['!cols_hidden'] || [];
      const ws = {};
      Object.keys(raw).forEach(function (k) { if (k !== '!rows_hidden' && k !== '!cols_hidden') ws[k] = raw[k]; });
      ws['!rows'] = rowsHidden.map(function (h) { return h ? { hidden: true } : null; });
      ws['!cols'] = colsHidden.map(function (h) { return h ? { hidden: true } : null; });
      Sheets[name] = ws;
    });
    return { SheetNames: wbJson.SheetNames, Sheets: Sheets, Workbook: { Sheets: wbJson.WorkbookSheetsMeta } };
  } finally {
    try { fs.unlinkSync(tmpXlsx); } catch (e) {}
    try { fs.unlinkSync(tmpJson); } catch (e) {}
  }
}

/* SheetJS `utils.sheet_to_json(ws, {defval})` เท่าที่ import-customers.js ใช้
   ★ ไล่พฤติกรรมจริงของ SheetJS สามข้อ เพราะทำพลาดแล้วข้อมูลเพี้ยนแบบไม่มีอะไรฟ้อง:
     1) ข้ามแถวที่ว่างทั้งแถว (SheetJS ตั้งต้น blankrows:false) — ไม่งั้นจะได้ลูกค้าเปล่าเป็นร้อยแถว
     2) หัวคอลัมน์ซ้ำกัน/ว่าง ต้องแยกชื่อกัน ไม่งั้นคอลัมน์หลังเขียนทับคอลัมน์หน้าเงียบๆ
       (ทะเบียนเก่า 46 คอลัมน์ มีหัวซ้ำได้จริง) */
function sheet_to_json(ws, opts) {
  opts = opts || {};
  const defval = opts.defval;
  const ref = ws && ws['!ref'];
  if (!ref) return [];
  const r = decode_range(ref);
  const seen = {}, hdr = [];
  for (let c = r.s.c; c <= r.e.c; c++) {
    const cell = ws[encode_cell({ r: r.s.r, c: c })];
    let name = (cell && cell.v !== undefined && cell.v !== null) ? String(cell.v).trim() : '';
    if (!name) name = '__EMPTY' + (c === r.s.c ? '' : '_' + c);
    if (seen[name] !== undefined) { seen[name]++; name = name + '_' + seen[name]; } else seen[name] = 0;
    hdr.push(name);
  }
  const out = [];
  for (let row = r.s.r + 1; row <= r.e.r; row++) {
    const o = {};
    let any = false;
    for (let c = r.s.c; c <= r.e.c; c++) {
      const cell = ws[encode_cell({ r: row, c: c })];
      const key = hdr[c - r.s.c];
      if (cell && cell.v !== undefined && cell.v !== null && cell.v !== '') { o[key] = cell.v; any = true; }
      else if (defval !== undefined) o[key] = defval;
    }
    if (any) out.push(o);
  }
  return out;
}

module.exports = { read: read, utils: { decode_range: decode_range, encode_cell: encode_cell, sheet_to_json: sheet_to_json } };
